options.css:
* {
  font-family: 'Open Sans', sans-serif;
}

.hover-container {
  width: 100%;
  height: 100%;
  padding: 15px;
  border-radius: 5px;
  background-color: rgba(20, 20, 20, 0.7);
  color: #d8d9da;
}

.title {
  font-size: 16px;
  font-weight: bold;
  margin-bottom: 15px;
  text-align: center;
  color: #00b0ff;
}

.hover-info {
  display: flex;
  justify-content: space-between;
  margin-bottom: 10px;
  padding: 8px;
  background: rgba(30, 30, 30, 0.5);
  border-radius: 3px;
}

.label {
  font-weight: 500;
}

.value {
  font-weight: bold;
}

.status {
  margin-top: 15px;
  font-style: italic;
  text-align: center;
  color: #999;
}

/* Animation for active hover */
@keyframes pulse {
  0% { opacity: 0.7; }
  50% { opacity: 1; }
  100% { opacity: 0.7; }
}

.active-hover {
  animation: pulse 1.5s infinite;
  color: #5ac8fa;
}

options.onDataHover:
// Clear any existing timeout to prevent flicker
if (htmlGraphics.hoverTimeout) {
  clearTimeout(htmlGraphics.hoverTimeout);
}

// Elements to update
const hoverTimeElement = htmlNode.getElementById('hover-time');
const hoverValueElement = htmlNode.getElementById('hover-value');
const hoverStatusElement = htmlNode.getElementById('hover-status');

if (hoverPayload && hoverPayload.point) {
  // Update last hover timestamp
  htmlGraphics.lastHoverTimestamp = Date.now();

  // Check if time exists in the hover payload
  if (hoverPayload.point.time !== undefined) {
    const hoverTime = new Date(hoverPayload.point.time);
    hoverTimeElement.textContent = hoverTime.toLocaleString();

    // Show active status
    hoverStatusElement.textContent = 'Hovering over data point';
    hoverStatusElement.classList.add('active-hover');

    // If we have a data value, display it
    if (hoverPayload.data && hoverPayload.rowIndex !== undefined) {
      const valueField = hoverPayload.data.fields.find(f => f.type === 'number');
      if (valueField) {
        const value = valueField.values.get(hoverPayload.rowIndex);
        hoverValueElement.textContent = value !== undefined ? value.toFixed(2) : '-';
      }
    }
  }
}

// Reset the timeout
htmlGraphics.hoverTimeout = setTimeout(() => {
  if (Date.now() - htmlGraphics.lastHoverTimestamp > 2000) {
    hoverTimeElement.textContent = 'No hover data yet';
    hoverValueElement.textContent = '-';
    hoverStatusElement.textContent = 'Move cursor over chart points';
    hoverStatusElement.classList.remove('active-hover');
  }
}, 2500);

options.onInit:
// Initialize the elements we'll update
const hoverTimeElement = htmlNode.getElementById('hover-time');
const hoverValueElement = htmlNode.getElementById('hover-value');
const hoverStatusElement = htmlNode.getElementById('hover-status');

// Store timestamp of last hover to control display
htmlGraphics.lastHoverTimestamp = 0;

// Function to reset display after period of inactivity
function setupHoverTimeout() {
  return setTimeout(() => {
    if (Date.now() - htmlGraphics.lastHoverTimestamp > 2000) {
      hoverTimeElement.textContent = 'No hover data yet';
      hoverValueElement.textContent = '-';
      hoverStatusElement.textContent = 'Move cursor over chart points';
      hoverStatusElement.classList.remove('active-hover');
    }
  }, 2500);
}

// Initial timeout
htmlGraphics.hoverTimeout = setupHoverTimeout();

options.onRender:
// Sets the value from the first series on every refresh
const htmlgraphicsValue = htmlNode.getElementById('htmlgraphics-value');

if (htmlgraphicsValue) {
  const valueField = data.series[0]?.fields[1];
  if (valueField) {
    const length = valueField.values.length;
    htmlgraphicsValue.textContent = valueField.values.get(length - 1);
  } else {
    htmlgraphicsValue.textContent = "No data"
  }
}
